steps.codeExample:
def dfs(no):
    if not no: return
    print(no.val)
    dfs(no.left)
    dfs(no.right)
def buscar_bst(no, alvo):
    if not no or no.val == alvo: return no
    return buscar_bst(no.left if alvo < no.val else no.right, alvo)

